parameters.jsCode:
// Sample notices for "Try it with sample notices": the shape the Actor returns, with
// deadlines counted from today. No Apify run, no cost. Titles start with [Sample].
//
// sampleDay 1 in "Your settings": five new tenders.
// sampleDay 2: four change notices for them (a moved deadline, an earlier deadline,
// a cancellation, corrected documents). The same run posts the brief.
// The first run that is not a sample run retires the sample rows.
let day = 1;
try {
  day = Number((($('Your settings').all()[0] || {}).json || {}).sampleDay) === 2 ? 2 : 1;
} catch (error) {
  day = 1;
}

const DAY_MS = 86400000;
const midday = (daysAhead) => {
  const d = new Date(Date.now() + daysAhead * DAY_MS);
  d.setUTCHours(11, 0, 0, 0);
  return d.toISOString();
};
const today = new Date().toISOString();
const procedure = (n) => `sample-0000-4000-8000-00000000000${n}`;

const base = (n, noticeNumber, fields) => ({
  source: 'ted',
  noticeId: `SAMPLE-${noticeNumber}-2026`,
  titleLanguage: 'eng',
  buyerCountry: 'DEU',
  noticeType: 'cn-standard',
  deadlineKind: 'tenders',
  estimatedValueCurrency: 'EUR',
  publishedAt: today,
  url: 'https://ted.europa.eu/en/',
  procedureId: procedure(n),
  isChange: false,
  changeReason: null,
  changeDescription: null,
  ...fields,
});

const tenders = [
  base(1, 101, { title: '[Sample] Germany – Software development services – Citizen portal', buyerName: 'Stadt Beispiel', estimatedValue: 480000, deadline: midday(7) }),
  base(2, 102, { title: '[Sample] Germany – IT consulting – Data platform support', buyerName: 'Land Beispiel', estimatedValue: 1200000, deadline: midday(2) }),
  base(3, 103, { title: '[Sample] Germany – Software maintenance – Library system', buyerName: 'Universität Beispiel', estimatedValue: null, estimatedValueCurrency: null, deadline: midday(20) }),
  base(4, 104, { title: '[Sample] Germany – Network equipment – School district', buyerName: 'Landkreis Beispiel', estimatedValue: 250000, deadline: midday(30), deadlineKind: 'requests' }),
  base(5, 105, { title: '[Sample] Germany – Cloud hosting – Open data portal', buyerName: 'Bundesamt Beispiel', estimatedValue: 90000, deadline: midday(15) }),
];

const change = (n, noticeNumber, fields) => ({
  ...tenders[n - 1],
  noticeId: `SAMPLE-${noticeNumber}-2026`,
  isChange: true,
  ...fields,
});
const changes = [
  change(3, 203, { deadline: midday(34), changeReason: 'update-add', changeDescription: 'Verlängerung der Angebotsfrist' }),
  change(5, 205, { deadline: midday(7), changeReason: 'cor-buy', changeDescription: 'Die Angebotsfrist wurde verkürzt.' }),
  change(4, 204, { changeReason: 'cancel-intent', changeDescription: 'Das Verfahren wird aufgehoben.' }),
  change(1, 201, { changeReason: 'update-add', changeDescription: 'Antworten auf Bieterfragen wurden ergänzt.' }),
];

return (day === 2 ? changes : tenders).map((json) => ({ json }));

