parameters.jsCode:
// Fold the notices of this run into the tenders table: one row per procurement procedure.
//
// TED publishes a change to a tender (a new deadline, corrected documents, a cancellation)
// as a new notice with its own number. The Actor marks it with isChange and gives every
// notice the procedureId it belongs to. So a notice either opens a new row, or updates the
// row of its procedure and leaves a change for the brief to report.
//
// Input: the table rows from "Get the tracked tenders". The notices are read from the Actor
// node, or from "Sample notices" in a sample run.
// Output: only the rows that were added or changed, with every column, for the save.

const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();

// The items of a node, or null when that node did not run in this execution.
function itemsOf(nodeName) {
  try {
    const node = $(nodeName);
    if (node.isExecuted === false) return null;
    return node.all();
  } catch (error) {
    return null;
  }
}

const sampleItems = itemsOf('Sample notices');
const sampleRun = sampleItems !== null;
const notices = (sampleRun ? sampleItems : itemsOf('Run EU Tenders Scraper (only new notices)') || [])
  .map((item) => item.json || {})
  .filter((n) => n && clean(n.noticeId) && clean(n.url) && !n.error);
const tableRows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => clean(row.procedureKey));

const SAMPLE = /^SAMPLE-/;
const CANCELLED = ['cancel', 'cancel-intent'];

// The workflow needs the Actor's procedureId field. Without it every notice would get its
// own row and a change notice would be posted as a new tender, so stop before saving.
if (notices.some((n) => !SAMPLE.test(clean(n.noticeId)) && !('procedureId' in n))) {
  throw new Error('The Actor returned notices without procedureId. Use the latest build of EU Tenders Scraper (TED); '
    + 'this workflow follows tenders by that field.');
}

// "792718-2026" sorts by year, then by number: TED numbers its notices in publication order.
function order(noticeId) {
  const m = /(\d+)-(\d{4})$/.exec(clean(noticeId));
  return m ? Number(m[2]) * 1e9 + Number(m[1]) : 0;
}

const keyOf = (n) => clean(n.procedureId) || `notice-${clean(n.noticeId)}`;
const cancels = (n) => n.isChange === true && CANCELLED.includes(clean(n.changeReason));
const nowIso = new Date().toISOString();

// What a notice says about the tender. Every table column is a string.
const facts = (n) => ({
  noticeId: clean(n.noticeId),
  title: clean(n.title) || '(no title published)',
  buyer: clean(n.buyerName) || 'Unknown buyer',
  country: clean(n.buyerCountry),
  deadline: clean(n.deadline),
  deadlineKind: clean(n.deadlineKind),
  url: clean(n.url),
  estimatedValue: clean(n.estimatedValue),
  estimatedValueCurrency: clean(n.estimatedValueCurrency),
  publishedAt: clean(n.publishedAt),
  status: cancels(n) ? 'cancelled' : 'open',
  changeReason: n.isChange === true ? clean(n.changeReason) || 'change' : '',
  changeDescription: n.isChange === true ? clean(n.changeDescription) : '',
});

const COLUMNS = [
  'procedureKey', 'noticeId', 'firstNoticeId', 'title', 'buyer', 'country', 'deadline', 'deadlineKind',
  'url', 'estimatedValue', 'estimatedValueCurrency', 'publishedAt', 'status',
  'changeReason', 'changeDescription', 'changedAt', 'previousDeadline', 'previousStatus', 'changes',
  'republished', 'addedAt', 'notifiedAt', 'changeNotifiedAt', 'reminded',
];

const table = new Map();
for (const row of tableRows) table.set(clean(row.procedureKey), row);
const touched = new Set();

// Oldest first, so two notices of one procedure in the same run are applied in order.
notices.sort((a, b) => order(a.noticeId) - order(b.noticeId));

for (const n of notices) {
  const key = keyOf(n);
  const row = table.get(key);

  if (!row) {
    // A procedure not seen before. A change notice can be the first one seen (the tender
    // started before you tracked it, or its first notice did not match your filters): it
    // is reported as new, with the change text.
    table.set(key, {
      procedureKey: key,
      ...facts(n),
      firstNoticeId: clean(n.noticeId),
      changedAt: '', previousDeadline: '', previousStatus: '', changes: '0', republished: '',
      addedAt: nowIso, notifiedAt: '', changeNotifiedAt: '', reminded: '',
    });
    touched.add(key);
    continue;
  }

  // The same notice again, or one older than the row already shows: nothing to do.
  if (order(n.noticeId) <= order(row.noticeId)) continue;

  // A buyer sometimes publishes the tender again as a fresh notice (not a change notice) and
  // then cancels the earlier notice. The notice does not say which one it cancels, and on TED
  // it was the earlier one in 4 of 5 such cases (October-November 2026). So after a fresh
  // notice, a "cancel" does not close the tender or bring back the old deadline: the row keeps
  // what it says, and the brief reports that a cancellation was published.
  const republished = clean(row.republished) === 'yes';
  const update = clean(n.changeReason) === 'cancel' && n.isChange === true && republished && clean(row.status) !== 'cancelled'
    ? { noticeId: clean(n.noticeId), changeReason: 'cancel-earlier', changeDescription: clean(n.changeDescription) }
    : facts(n);

  const next = { ...row, ...update, changes: String((Number(row.changes) || 0) + 1) };
  if (n.isChange !== true) next.republished = 'yes';
  if (clean(row.notifiedAt)) {
    // The tender was already posted. Keep what Slack last showed (deadline and status)
    // until the brief reports the change; a second change before that keeps the first snapshot.
    const pending = clean(row.changedAt) && !clean(row.changeNotifiedAt);
    next.previousDeadline = pending ? clean(row.previousDeadline) : clean(row.deadline);
    next.previousStatus = pending ? clean(row.previousStatus) || 'open' : clean(row.status) || 'open';
    next.changedAt = clean(n.publishedAt) || nowIso;
    next.changeNotifiedAt = '';
  }
  // Not posted yet: the brief will show the tender as new, with its latest notice.
  table.set(key, next);
  touched.add(key);
}

// Rows from "Try it with sample notices" are retired by the first run that is not a sample run.
if (!sampleRun) {
  for (const [key, row] of table) {
    if (SAMPLE.test(clean(row.firstNoticeId)) && clean(row.status) !== 'retired') {
      table.set(key, { ...row, status: 'retired' });
      touched.add(key);
    }
  }
}

return [...touched].map((key) => {
  const row = table.get(key);
  const json = {};
  for (const column of COLUMNS) json[column] = clean(row[column]);
  return { json };
});

// Build the morning brief from the tenders table: what changed on tenders you already saw,
// which deadlines are near, and what is new. One Slack message, or several when it is long.
//
// A line is posted once. Each message carries the rows it shows and the stamps they get
// after Slack accepts it ("List what Slack accepted" and "Stamp the posted tenders"), so
// a message Slack rejects is built again on the next run.
//
// Input: every row of the table, read after this run's notices were saved.
// Settings come from "Your settings".

function setting(name, fallback) {
  try {
    const items = $('Your settings').all();
    const value = items.length ? (items[0].json || {})[name] : undefined;
    if (value !== undefined && value !== null && String(value).trim()) return String(value).trim();
  } catch (error) {
    // No settings node in this run: use the fallback.
  }
  return fallback;
}
function validZone(name) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: name }).format(new Date());
    return name;
  } catch (error) {
    return 'Europe/Brussels';
  }
}
const TIME_ZONE = validZone(setting('timezone', 'Europe/Brussels'));
// Days before a deadline when a tender is listed under "Due soon", for example 7 and 2.
const REMIND_DAYS = setting('remindDaysBefore', '7,2').split(',')
  .map((s) => s.trim()).filter((s) => /^\d+$/.test(s))
  .map(Number).filter((n) => n <= 365)
  .sort((a, b) => a - b);
// "all": every change notice of a tracked tender. "deadline": only moved deadlines and cancellations.
const CHANGE_ALERTS = setting('changeAlerts', 'all').toLowerCase() === 'deadline' ? 'deadline' : 'all';

const DAY_MS = 86400000;
const LIMIT = 3900; // chat.postMessage asks for text under 4,000 characters.
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const now = typeof $now !== 'undefined' && $now && typeof $now.toJSDate === 'function' ? $now.toJSDate() : new Date();
const nowIso = now.toISOString();

const zoneFormat = new Intl.DateTimeFormat('en-CA', {
  timeZone: TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
const local = (date) => {
  const p = {};
  for (const part of zoneFormat.formatToParts(date)) p[part.type] = part.value;
  return { day: `${p.year}-${p.month}-${p.day}`, time: `${p.hour}:${p.minute}` };
};
const dayNumber = (day) => Math.floor(Date.UTC(Number(day.slice(0, 4)), Number(day.slice(5, 7)) - 1, Number(day.slice(8, 10))) / DAY_MS);
const today = dayNumber(local(now).day);

// A deadline is a moment (ISO 8601); its day is the calendar day in TIME_ZONE.
// A date without a time is that day, and it ends when the day ends.
function deadlineOf(value) {
  const text = clean(value);
  if (!text) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    const day = dayNumber(text);
    return { text, day, days: day - today, past: day < today, key: text };
  }
  const d = new Date(text);
  if (Number.isNaN(d.getTime())) return null;
  const at = local(d);
  const day = dayNumber(at.day);
  return { text: `${at.day} ${at.time}`, day, days: day - today, past: d.getTime() <= now.getTime(), key: d.toISOString() };
}
// Whether a deadline had passed at an earlier moment (true when that moment is unknown).
function closedBy(value, moment) {
  const at = new Date(clean(moment));
  if (!clean(moment) || Number.isNaN(at.getTime())) return true;
  const text = clean(value);
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return dayNumber(text) < dayNumber(local(at).day);
  const d = new Date(text);
  return !Number.isNaN(d.getTime()) && d.getTime() <= at.getTime();
}
const sameDeadline = (a, b) => {
  const x = deadlineOf(a);
  const y = deadlineOf(b);
  return x && y ? x.key === y.key : !x && !y;
};
const inDays = (days) => (days === 0 ? 'today' : days === 1 ? 'tomorrow' : `in ${days} days`);

// The nearest reminder day the deadline has reached, with the deadline it was counted for.
// A moved deadline gives a new key, so the reminders run again for the new date.
function reminderKey(row) {
  const deadline = deadlineOf(row.deadline);
  if (!deadline || deadline.past || deadline.days < 0) return '';
  const reached = REMIND_DAYS.find((days) => deadline.days <= days);
  return reached === undefined ? '' : `${reached}|${deadline.key}`;
}

// Slack decodes &, < and > as HTML entities, so escape them in visible text.
const escape = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Slack reads the first pipe in <url|label> as the separator, so keep it out of both parts.
const linkText = (value) => String(value ?? '').replace(/\|/g, '-');
const linkUrl = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '%3C').replace(/>/g, '%3E').replace(/\|/g, '%7C');
// Text from a notice must not start or end Slack formatting.
const plain = (value) => escape(value).replace(/[*_~`]/g, ' ').replace(/\s+/g, ' ').trim();
const short = (value, max) => {
  const chars = Array.from(String(value ?? ''));
  return chars.length > max ? chars.slice(0, max - 1).join('').trimEnd() + '…' : chars.join('');
};
const money = (value, currency) => {
  const n = Number(value);
  if (clean(value) === '' || !Number.isFinite(n)) return '';
  const digits = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return currency ? `${clean(currency)} ${digits}` : digits;
};
const headline = (row) => `<${linkUrl(clean(row.url))}|${linkText(plain(short(clean(row.title) || '(no title published)', 180)))}>`;

// The reason codes of TED's change notices, with the labels of the official code list.
const REASONS = {
  'update-add': 'information updated',
  'cor-buy': 'buyer correction',
  'cor-pub': 'publisher correction',
  'cor-esen': 'eSender correction',
  'info-release': 'information now available',
  'cancel': 'notice cancelled',
  'cancel-intent': 'cancellation intention',
  'susp-review': 'procedure suspended for a review',
  'cancel-earlier': 'a cancellation was published, see below',
};
const reasonOf = (row) => REASONS[clean(row.changeReason)] || '';
const quoteOf = (row) => {
  const text = plain(short(clean(row.changeDescription), 220));
  return text ? `\n   _“${text}”_` : '';
};

// "closes 2026-12-04 12:00 (in 21 days)"; in restricted and negotiated procedures the
// deadline is for requests to participate.
function closing(row) {
  const deadline = deadlineOf(row.deadline);
  const requests = clean(row.deadlineKind) === 'requests';
  if (!deadline) return 'no deadline published';
  if (deadline.past) return `${requests ? 'requests to participate closed' : 'closed'} ${deadline.text}`;
  return `${requests ? 'requests to participate by' : 'closes'} ${deadline.text} (${inDays(deadline.days)})`;
}
const whoAndValue = (row) => [
  plain(short(clean(row.buyer) || 'Unknown buyer', 160)),
  plain(short(clean(row.country), 40)),
  money(row.estimatedValue, row.estimatedValueCurrency),
].filter(Boolean);

const rows = $input.all().map((item) => item.json || {})
  .filter((row) => clean(row.procedureKey) && clean(row.url) && clean(row.status) !== 'retired');

// ---- 1. Changed: tenders already posted whose latest notice is a change not reported yet.
const changed = [];
const changedKeys = new Set();
for (const row of rows) {
  if (!clean(row.notifiedAt) || !clean(row.changedAt) || clean(row.changeNotifiedAt)) continue;
  const before = clean(row.previousStatus) || 'open';
  const status = clean(row.status) || 'open';
  const was = deadlineOf(row.previousDeadline);
  const is = deadlineOf(row.deadline);
  let rank;
  let what;
  if (status === 'cancelled' && before !== 'cancelled') {
    rank = 0;
    // "cancel-intent" is the buyer's announcement; "cancel" withdraws the notice.
    what = clean(row.changeReason) === 'cancel-intent' ? '*Cancellation announced*' : `*Cancelled*${reasonOf(row) ? ` · ${reasonOf(row)}` : ''}`;
  } else if (status !== 'cancelled' && before === 'cancelled') {
    rank = 1;
    // A fresh notice after a cancellation publishes the tender again; a change notice only updates it.
    what = `${clean(row.changeReason) ? '*Updated after a cancellation*' : '*Published again*'} · ${closing(row)}`;
  } else if (status === 'cancelled') {
    continue; // Still cancelled: nothing new to tell.
  } else if (!sameDeadline(row.previousDeadline, row.deadline)) {
    rank = 1;
    if (was && is) {
      const days = is.day - was.day;
      const shift = days === 0 ? 'same day' : `${Math.abs(days)} day${Math.abs(days) === 1 ? '' : 's'} ${days > 0 ? 'later' : 'earlier'}`;
      what = `*Deadline moved* ${was.text} → ${is.text} (${shift}) · ${is.past ? 'now closed' : `closes ${inDays(is.days)}`}`;
    } else if (is) {
      what = `*Deadline set* · ${closing(row)}`;
    } else {
      what = `*Deadline removed* (was ${was.text})`;
    }
  } else if (clean(row.changeReason) === 'cancel-earlier') {
    if (CHANGE_ALERTS === 'deadline') continue;
    rank = 2;
    // Usually the cancelled notice is the earlier one, but the notice does not say.
    what = `*A cancellation was published after this tender was published again* · check the notice · latest notice ${closing(row)}`;
  } else {
    if (CHANGE_ALERTS === 'deadline') continue; // Stays pending; a later deadline move still compares with what Slack showed.
    rank = 2;
    what = `*Updated*${reasonOf(row) ? ` · ${reasonOf(row)}` : ''} · ${closing(row)}`;
  }
  changedKeys.add(clean(row.procedureKey));
  changed.push({
    rank,
    sort: clean(row.changedAt),
    text: `• ${headline(row)}\n   ${what}${quoteOf(row)}`,
    stamp: { notifiedAt: clean(row.notifiedAt), changeNotifiedAt: nowIso, reminded: status === 'cancelled' ? clean(row.reminded) : reminderKey(row) || clean(row.reminded) },
    row,
  });
}
changed.sort((a, b) => (a.rank - b.rank) || b.sort.localeCompare(a.sort));

// ---- 2. Due soon: posted, open tenders whose deadline reached a reminder day not sent yet.
// A day the workflow did not run is caught up on the next run.
const due = [];
for (const row of rows) {
  if (!clean(row.notifiedAt) || (clean(row.status) || 'open') !== 'open') continue;
  if (changedKeys.has(clean(row.procedureKey))) continue; // Its change line already shows the days left.
  const key = reminderKey(row);
  if (!key || key === clean(row.reminded)) continue;
  const deadline = deadlineOf(row.deadline);
  const requests = clean(row.deadlineKind) === 'requests';
  due.push({
    sort: deadline.key,
    text: `• ${headline(row)}\n   *${inDays(deadline.days)}* · ${requests ? 'requests to participate by' : 'closes'} ${deadline.text} · ${plain(short(clean(row.buyer) || 'Unknown buyer', 120))}`,
    stamp: { notifiedAt: clean(row.notifiedAt), changeNotifiedAt: clean(row.changeNotifiedAt), reminded: key },
    row,
  });
}
due.sort((a, b) => a.sort.localeCompare(b.sort));

// ---- 3. New: tenders not posted yet, newest first.
const fresh = [];
for (const row of rows) {
  if (clean(row.notifiedAt) || (clean(row.status) || 'open') !== 'open') continue;
  // Already closed when it was first seen: the row waits, and is posted if a later notice
  // reopens the tender. A row that was open when it was saved is posted even if it has
  // closed since (a brief Slack rejected is sent on the next run).
  const closes = deadlineOf(row.deadline);
  if (closes && closes.past && closedBy(row.deadline, row.addedAt)) continue;
  const facts = [...whoAndValue(row), closing(row)];
  // The first notice seen can itself be a change of an earlier one.
  const note = clean(row.changeReason) ? `\n   change notice${reasonOf(row) ? ` · ${reasonOf(row)}` : ''}${quoteOf(row).replace('\n   ', ' · ')}` : '';
  fresh.push({
    sort: clean(row.publishedAt) || clean(row.addedAt),
    text: `• ${headline(row)}\n   ${facts.join(' · ')}${note}`,
    stamp: { notifiedAt: nowIso, changeNotifiedAt: clean(row.changedAt) ? nowIso : clean(row.changeNotifiedAt), reminded: reminderKey(row) || clean(row.reminded) },
    row,
  });
}
fresh.sort((a, b) => b.sort.localeCompare(a.sort));

const total = changed.length + due.length + fresh.length;
if (total === 0) return [];

const counts = [
  changed.length ? `${changed.length} changed` : '',
  due.length ? `${due.length} due soon` : '',
  fresh.length ? `${fresh.length} new` : '',
].filter(Boolean).join(' · ');
const heading = `*EU tenders — ${counts}*`;
const footer = `_Times are ${TIME_ZONE}. One line per procedure: a change notice updates its tender and is not posted as new._`;
const sections = [
  { title: '*Changed*', entries: changed },
  { title: '*Due soon*', entries: due },
  { title: '*New*', entries: fresh },
].filter((section) => section.entries.length > 0);

// Pack the lines into messages under LIMIT. A section that continues in the next
// message repeats its title there.
const room = LIMIT - heading.length - footer.length - 40;
const messages = [];
let current = null;
const open = () => {
  current = { lines: [], entries: [], used: 0, section: '' };
  messages.push(current);
};
open();
for (const section of sections) {
  for (const entry of section.entries) {
    const text = entry.text.length > room - 40 ? entry.text.slice(0, room - 41) + '…' : entry.text;
    const needsTitle = current.section !== section.title;
    const cost = text.length + 1 + (needsTitle ? section.title.length + 2 : 0);
    if (current.used + cost > room && current.entries.length > 0) open();
    if (current.section !== section.title) {
      const title = current.entries.length === 0 && messages.length > 1 && messages[messages.length - 2].section === section.title
        ? `${section.title} (continued)` : section.title;
      if (current.lines.length > 0) current.lines.push('');
      current.lines.push(title);
      current.used += title.length + 2;
      current.section = section.title;
    }
    current.lines.push(text);
    current.used += text.length + 1;
    current.entries.push(entry);
  }
}

return messages.map((message, index) => {
  const title = messages.length > 1 ? `${heading} (${index + 1}/${messages.length})` : heading;
  const lines = [title, '', ...message.lines];
  if (index === messages.length - 1) lines.push('', footer);
  return {
    json: {
      message: lines.join('\n'),
      changed: changed.length,
      dueSoon: due.length,
      new: fresh.length,
      shown: message.entries.length,
      // What to stamp on each row after Slack accepts this message.
      posted: message.entries.map((entry) => ({ procedureKey: clean(entry.row.procedureKey), ...entry.stamp })),
    },
  };
});

// After Slack, list the stamps for the rows whose message Slack accepted.
// "Post the brief to Slack" has an error output: this node receives only the accepted
// messages, and a rejected one goes to "Stop the run on a rejected message".
// "Build the morning brief" put the rows and stamps of each message on its item.
//
// Which messages were accepted:
// - every message came through: all of them (no pairing needed);
// - some failed: the messages whose input position Slack reports in pairedItem;
// - some failed and the position is not readable: none, so nothing is stamped wrongly
//   and the next run posts those lines again.
const parts = $('Build the morning brief').all().map((item) => item.json || {});
const accepted = $input.all();
const positionOf = (item) => {
  let p = item && item.pairedItem;
  if (Array.isArray(p)) p = p[0];
  const n = p && typeof p === 'object' ? p.item : p;
  return Number.isInteger(n) ? n : -1;
};

let posted = [];
if (accepted.length >= parts.length) {
  posted = parts.map((part, index) => index);
} else {
  const positions = accepted.map(positionOf);
  if (positions.every((n) => n >= 0 && n < parts.length)) posted = positions;
}

const text = (value) => String(value ?? '').trim();
const seen = new Set();
const out = [];
for (const index of posted) {
  for (const stamp of (parts[index] || {}).posted || []) {
    const key = text(stamp && stamp.procedureKey);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push({
      json: {
        procedureKey: key,
        notifiedAt: text(stamp.notifiedAt),
        changeNotifiedAt: text(stamp.changeNotifiedAt),
        reminded: text(stamp.reminded),
      },
    });
  }
}

return out;

// Turn a failed Actor call or a failed search into one item for "Stop the run on a
// failed search", so the execution fails instead of looking successful. The Error
// Trigger then posts the failure once.
//
// The EU Tenders Actor returns no items on a normal empty day, not an error item, so
// any item with an error field is a failure. There is no "empty" error type to exempt.
// The earlier warning branch is not used: this branch fails the run, and posting a
// Slack message here as well would report the same failure twice.

const rows = $input.all().map((item) => item.json || {});

// A run that returns as many notices as maxItems allows has probably left older ones
// unread. They are saved first (the save branch sits above this one), then the run fails
// so the alert tells you to raise maxItems.
function cap() {
  try {
    // The same reading as the Actor input: a whole number from 1 to 1000, otherwise 250.
    const value = Math.floor(Number((($('Your settings').all()[0] || {}).json || {}).maxItems));
    return value >= 1 ? Math.min(value, 1000) : 250;
  } catch (error) {
    return 250;
  }
}
const returned = rows.filter((row) => row && row.noticeId && !row.error).length;
const maxItems = cap();

function text(value, max) {
  if (value === null || value === undefined) return '';
  let s = String(value).replace(/\s+/g, ' ').trim();
  if (max) {
    const chars = Array.from(s);
    if (chars.length > max) s = chars.slice(0, max - 1).join('').trimEnd() + '…';
  }
  return s;
}

function describe(error) {
  if (typeof error === 'string') return text(error, 300);
  if (!error || typeof error !== 'object') return '';
  const type = text(error.type);
  const message = text(error.message, 300);
  return [type, message].filter(Boolean).join(': ');
}

const failed = rows.filter((row) => row && row.error);
if (!failed.length && maxItems > 0 && returned >= maxItems) {
  return [{
    json: {
      message: 'The Actor returned ' + returned + ' notices, the maxItems limit. They are saved and posted, but ' +
        'older matching notices may not have been fetched. Raise maxItems in Your settings (above 300, also ' +
        'raise Maximum Cost per Run in the Apify node), or narrow the filters.',
      failed: 0,
    },
  }];
}
if (!failed.length) return [];

const details = [];
for (const row of failed) {
  const detail = describe(row.error);
  if (detail && details.indexOf(detail) < 0) details.push(detail);
}

const shown = details.slice(0, 3).join('; ');
const more = details.length > 3 ? '; and ' + (details.length - 3) + ' more' : '';
const noun = failed.length === 1 ? 'search' : 'searches';

return [{
  json: {
    message: failed.length + ' ' + noun + ' failed in this run' +
      (shown ? ' (' + shown + more + ')' : '') +
      '. The run is stopped so the failure is visible.',
    failed: failed.length,
  },
}];

